(() => {
 const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let resolveReady,setup=false,needsToken=false,teamUsers=[];
 const client=window.TalentClient={ready:new Promise(resolve=>resolveReady=resolve),csrf:'',user:null,company:null,consentVersion:'2026-10-v1'};
 client.request=async(path,body)=>{
  const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':client.csrf},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(300000)});
  const data=await r.json();if(!r.ok){if(r.status===401&&client.user&&!path.startsWith('/api/auth/password'))client.expired();throw Object.assign(new Error(data.error||'请求失败'),{status:r.status})}return data;
 };
 client.expired=()=>{sessionStorage.removeItem('talentlens-client-'+client.user?.id);location.reload()};
 const signedIn=data=>{client.csrf=data.csrf;client.user=data.user;client.company=data.company;if(data.user.mustChangePassword){$('#password-message').textContent='首次登录，请修改管理员交付的初始密码。';$('#password-close').hidden=true;$('#password-dialog').showModal();return}document.body.classList.remove('requires-auth');$('#auth-shell').hidden=true;$('#team-settings').hidden=data.user.role!=='admin';$('#session-user').textContent=data.user.name+' · '+(data.user.role==='admin'?'管理员':'顾问');$('#company-name').textContent=data.company.name;resolveReady(data)};
 const showAuth=data=>{setup=!data.initialized;needsToken=!!data.setupRequiresToken;$('#auth-title').textContent=setup?'创建客户工作空间':'登录 TalentLens';$('#auth-description').textContent=setup?'首次创建管理员账号；已有岗位和评估结果将迁入。':'登录后继续处理你负责的岗位与人才。';$('#setup-fields').hidden=!setup;$('#setup-token-field').hidden=!setup||!needsToken;$('#setup-token').required=setup&&needsToken;$('#company').required=setup;$('#admin-name').required=setup;$('#login-password').autocomplete=setup?'new-password':'current-password';$('#login-password').minLength=setup?12:1;$('#login-submit').textContent=setup?'创建工作空间':'登录';$('#auth-shell').hidden=false};
 $('#login-form').onsubmit=async e=>{e.preventDefault();$('#login-submit').disabled=true;$('#auth-message').textContent='';try{const data=await client.request('/api/auth/'+(setup?'setup':'login'),{username:$('#login-username').value,password:$('#login-password').value,companyName:$('#company').value,name:$('#admin-name').value,setupToken:$('#setup-token').value});$('#login-password').value='';$('#setup-token').value='';signedIn(data)}catch(e){$('#auth-message').textContent=e.message}finally{$('#login-submit').disabled=false}};
 $('#logout').onclick=async()=>{try{await client.request('/api/auth/logout',{});sessionStorage.removeItem('talentlens-client-'+client.user.id);location.reload()}catch(e){$('#message').textContent=e.message}};
 $('#password-logout').onclick=()=>$('#logout').click();$('#password-dialog').oncancel=e=>{if(client.user?.mustChangePassword)e.preventDefault()};$('#password-open').onclick=()=>$('#password-dialog').showModal();$('#password-close').onclick=()=>{$('#password-dialog').close();$('#password-form').reset()};
 $('#password-form').onsubmit=async e=>{e.preventDefault();$('#password-save').disabled=true;try{await client.request('/api/auth/password',{currentPassword:$('#current-password').value,password:$('#new-password').value});$('#password-form').reset();client.expired()}catch(e){$('#password-message').textContent=e.message}finally{$('#password-save').disabled=false}};
 client.refreshUsage=async()=>{const u=await client.request('/api/usage');$('#usage-status').textContent=`今日模型调用 ${u.calls}/${u.dailyCalls} · Token ${u.tokens.toLocaleString()}/${u.dailyTokens.toLocaleString()}`;return u};
 const renderUsers=()=>{$('#team-users').innerHTML=teamUsers.map(u=>`<div class="team-user"><div><strong>${esc(u.name)}</strong><small>${esc(u.username)} · ${u.role==='admin'?'管理员':'顾问'} · ${u.enabled?'启用':'停用'}</small></div>${u.id===client.user.id?'<span class="muted">当前账号</span>':`<button class="secondary" data-user-toggle="${esc(u.id)}">${u.enabled?'停用':'启用'}</button>`}</div>`).join('');$('#job-owner').innerHTML=teamUsers.filter(u=>u.enabled).map(u=>`<option value="${esc(u.id)}">${esc(u.name)}</option>`).join('');window.dispatchEvent(new CustomEvent('talentlens-team-loaded'))};
 $('#team-settings').onclick=async()=>{try{const [users,u,events,health]=await Promise.all([client.request('/api/admin/users'),client.refreshUsage(),client.request('/api/admin/audit'),client.request('/api/admin/health')]);teamUsers=users.users;renderUsers();$('#daily-calls').value=u.dailyCalls;$('#daily-tokens').value=u.dailyTokens;$('#db-health').textContent='数据库 '+health.database+' · 自动备份'+(health.lastBackup?' '+new Date(health.lastBackup).toLocaleString():'已配置');$('#audit-events').innerHTML=events.events.map(e=>`<p>${esc(new Date(e.created_at).toLocaleString())} · ${esc(e.actor_name||'系统')} · ${esc(e.action)}</p>`).join('');$('#team-dialog').showModal()}catch(e){$('#message').textContent=e.message}};
 $('#team-close').onclick=()=>{$('#team-dialog').close();$('#create-user-form').reset();$('#team-message').textContent=''};
 $('#create-user-form').onsubmit=async e=>{e.preventDefault();$('#create-user').disabled=true;try{const result=await client.request('/api/admin/users',{username:$('#new-username').value,name:$('#new-name').value,password:$('#user-password').value,role:$('#new-role').value});teamUsers=result.users;renderUsers();$('#create-user-form').reset();$('#team-message').textContent='账号已创建，请通过客户认可的渠道交付登录信息。'}catch(e){$('#team-message').textContent=e.message}finally{$('#create-user').disabled=false}};
 $('#team-users').onclick=async e=>{const u=teamUsers.find(u=>u.id===e.target.dataset.userToggle);if(!u)return;try{const result=await client.request('/api/admin/users',{id:u.id,name:u.name,role:u.role,enabled:!u.enabled});teamUsers=result.users;renderUsers();$('#team-message').textContent=u.enabled?'已停用，已有登录会话已撤销。':'已启用。'}catch(e){$('#team-message').textContent=e.message}};
 $('#budget-form').onsubmit=async e=>{e.preventDefault();try{await client.request('/api/admin/limits',{dailyCalls:Number($('#daily-calls').value),dailyTokens:Number($('#daily-tokens').value)});await client.refreshUsage();$('#team-message').textContent='预算上限已保存，按 UTC 日期重置。'}catch(e){$('#team-message').textContent=e.message}};
 client.getTeamUsers=()=>teamUsers;
 client.request('/api/auth/status').then(data=>data.authenticated?signedIn(data):showAuth(data)).catch(e=>{$('#auth-message').textContent='服务连接失败：'+e.message;$('#auth-shell').hidden=false});
})();
